#!/bin/bash -ue
# Regenerates every pinned Steam depot manifest. Anonymous Steam accounts can
# only fetch a depot's *current* manifest, so any pin left behind here starts
# failing with a 401 on a clean fetch as soon as Valve ships an update -- every
# steamapps*.bzl must be regenerated by this script, never edited by hand.
cd "$(dirname "$0")"

# Counter-Strike: Source Dedicated Server.
bazel run @rules_steam//generate -- --out "$(pwd)/steamapps.bzl" \
  --app 232330 --repo counterstrikesource_dedicated

# Team Fortress 2 Dedicated Server, for the 64-bit launcher CS:S lacks (see
# MODULE.bazel). The filter keeps a multi-GB app down to a ~100KB download.
bazel run @rules_steam//generate -- --out "$(pwd)/steamapps_tf2.bzl" \
  --app 232250 --repo tf2_dedicated \
  --files 'regex:^srcds_linux64$' \
  --files 'regex:^bin/linux64/libsteam_api\.so$'

# Steamworks SDK Redist, for the 64-bit steamclient.so (see MODULE.bazel).
bazel run @rules_steam//generate -- --out "$(pwd)/steamapps_steamworks.bzl" \
  --app 1007 --repo steamworks_sdk_redist

bazel mod deps
